
const S={lang:'ru',workspace:'public',section:'home',privateTab:'overview',wholesaleTab:'matrix',adminTab:'readiness',store:'HQ',mode:'preview'};
const LIVE={configured:false,phase:'preview_only',authorizedSurfaces:[],selectedSurface:'public',assuranceLevel:null,user:null,access:null,error:null,data:null};
function liveAuthenticated(){return LIVE.phase==='authenticated'&&!!LIVE.user}
function liveCan(surface){return liveAuthenticated()&&LIVE.authorizedSurfaces.includes(surface)}
function applyLiveState(next={}){Object.assign(LIVE,next||{});if(!liveAuthenticated()&&S.mode==='live'){S.mode='preview';S.workspace='public';S.section='home'}nav()}
window.addEventListener('mp-live-auth-state',e=>applyLiveState(e.detail||{}));
window.addEventListener('mp-live-data',e=>{LIVE.data=e.detail||null;nav();if(S.section==='private')renderPrivate();if(S.section==='wholesale')renderWholesale();if(S.section==='admin')renderAdmin()});
window.addEventListener('mp-live-public-catalogue',e=>{const payload=e.detail||{};const rows=Array.isArray(payload.products)?payload.products:[];if(!rows.length)return;products=rows.map((p,i)=>({id:p.id||('live-'+i),style:p.style_code||p.style||('LIVE-'+(i+1)),name:p.name||p.title||p.style_code||'Product',cat:p.category||p.subcategory||'Other',season:p.season||'',size:'-',price:null,delivery:null,verified:false,media:Boolean(p.hero_image_url),hero:p.hero_image_url||null,source:'live'}));renderCatalog();nav()});
const DEMO_KEY='mp-v30-demo';
const DEMO_VERSION=315;
const seedDemo=()=>({
  version:DEMO_VERSION,
  wishlist:[],
  fit:{jacket:'50',trouser:'50',fit:'Relaxed tailored',height:'182 cm',confidence:.86},
  privateOrder:{code:'PRI-2601',client:'Private Client',stage:'draft',total:'€ 1,280',rev:1,shipment:'Not allocated',payment:'not_requested',delivered:false},
  wholesaleOrders:{
    HQ:{code:'WH-2604',client:'Maison Europe HQ',stage:'draft',total:'€ 22,480',rev:2,shipment:'Not allocated'},
    Paris:{code:'WH-2608',client:'Maison Paris',stage:'draft',total:'€ 18,640',rev:7,shipment:'Not allocated'},
    Dubai:{code:'WH-2611',client:'Dubai Boutique',stage:'draft',total:'€ 12,920',rev:4,shipment:'Not allocated'}
  },
  sizeMatrix:{HQ:[1,2,4,4,2],Paris:[1,2,4,4,2],Dubai:[2,2,3,3,2]},
  reorder:{status:'none',style:'MP-2401',suggestedQty:16,store:'Paris',newOrder:null},
  completed:{privateDelivery:false,wholesaleParisDelivery:false,claimClosed:false,reorderConverted:false},
  claim:{id:'CLM-104',state:'none',reason:'damage',quantity:4,executed:0,resolution:null,order:'PRI-2601'},
  service:{status:'open',type:'Appointment'},
  events:[{at:new Date().toISOString(),type:'demo_seeded',detail:'v31.5 canonical lifecycle state initialized'}]
});
function demoStore(){
  try{
    const raw=JSON.parse(localStorage.getItem(DEMO_KEY)||'null');
    if(!raw||raw.version!==DEMO_VERSION){const fresh=seedDemo();localStorage.setItem(DEMO_KEY,JSON.stringify(fresh));return fresh}
    return raw;
  }catch{const fresh=seedDemo();localStorage.setItem(DEMO_KEY,JSON.stringify(fresh));return fresh}
}
function demoReplace(next){localStorage.setItem(DEMO_KEY,JSON.stringify(next));return next}
function demoSave(patch){return demoReplace({...demoStore(),...patch})}
function mutateDemo(fn){const cur=demoStore();const next=fn(structuredClone(cur))||cur;next.version=DEMO_VERSION;return demoReplace(next)}
function addDemoEvent(type,detail){mutateDemo(s=>{s.events=[{at:new Date().toISOString(),type,detail},...(s.events||[])].slice(0,80);return s})}
function toggleDemoWishlist(id){mutateDemo(s=>{const w=new Set(s.wishlist||[]);w.has(id)?w.delete(id):w.add(id);s.wishlist=[...w];s.events=[{at:new Date().toISOString(),type:'wishlist',detail:(w.has(id)?'added ':'removed ')+id},...(s.events||[])].slice(0,80);return s});toast((demoStore().wishlist||[]).includes(id)?'Добавлено в demo wishlist':'Удалено из demo wishlist')}
function badgeForStage(stage){const good=['delivered','resolved','closed','approved','advance_confirmed','converted'].includes(stage);const warn=['submitted','negotiation','approval_pending','proforma_issued','advance_pending','reserved','allocated','fulfillment','shipped','partial_shipment','execution_pending','offered','proposed','buyer_approved','brand_approved'].includes(stage);return good?'good':warn?'warn':''}
function prettyStage(stage){return String(stage||'').replaceAll('_',' ')}
function advancePrivate(action){
  mutateDemo(s=>{const o=s.privateOrder;
    const map={
      create:['draft','draft'],submit:['draft','submitted'],accept_revision:['negotiation','approval_pending'],submit_payment:['proforma_issued','advance_pending']
    };
    if(action==='create'){s.privateOrder={code:'PRI-'+String(Date.now()).slice(-4),client:'Private Client',stage:'draft',total:'€ 1,280',rev:1,shipment:'Not allocated',payment:'not_requested',delivered:false}}
    else if(map[action]&&o.stage===map[action][0]){o.stage=map[action][1];if(action==='accept_revision')o.rev+=1;if(action==='submit_payment')o.payment='submitted'}
    s.events=[{at:new Date().toISOString(),type:'private_'+action,detail:s.privateOrder.code+' → '+s.privateOrder.stage},...(s.events||[])].slice(0,80);return s
  });renderPrivate();renderAdmin();renderQA();toast('Private workflow: '+prettyStage(demoStore().privateOrder.stage))
}
function advanceWholesale(action){
  mutateDemo(s=>{const o=s.wholesaleOrders[S.store];
    if(action==='save_revision'){o.rev+=1;o.stage='draft'}
    if(action==='submit'&&o.stage==='draft')o.stage='submitted';
    if(action==='accept_revision'&&o.stage==='negotiation')o.stage='approval_pending';
    if(action==='submit_payment'&&o.stage==='proforma_issued')o.stage='advance_pending';
    if(action==='copy'){const src=o;s.wholesaleOrders.HQ={...src,code:'WH-'+String(Date.now()).slice(-4),client:'Maison Europe HQ',stage:'draft',shipment:'Not allocated',rev:1}}
    s.events=[{at:new Date().toISOString(),type:'wholesale_'+action,detail:o.code+' · '+S.store+' → '+o.stage},...(s.events||[])].slice(0,80);return s
  });renderWholesale();renderAdmin();renderQA();toast('Wholesale workflow updated')
}
function adminAction(action,target){
  mutateDemo(s=>{
    let o=target==='private'?s.privateOrder:s.wholesaleOrders[target||S.store];
    if(action==='brand_revision'&&o.stage==='submitted'){o.stage='negotiation';o.rev+=1}
    if(action==='approve'&&o.stage==='approval_pending')o.stage='approved';
    if(action==='issue_proforma'&&o.stage==='approved')o.stage='proforma_issued';
    if(action==='verify_payment'&&o.stage==='advance_pending'){o.stage='advance_confirmed';o.payment='verified'}
    if(action==='allocate'&&o.stage==='advance_confirmed'){o.stage='allocated';o.shipment='Allocated'}
    if(action==='create_shipment'&&o.stage==='allocated'){o.stage='fulfillment';o.shipment='Planned'}
    if(action==='dispatch_shipment'&&['fulfillment','partial_shipment'].includes(o.stage)){o.stage='shipped';o.shipment='In transit'}
    if(action==='deliver'&&o.stage==='shipped'){o.stage='delivered';o.shipment='Delivered';o.delivered=true;if(target==='Paris')s.completed.wholesaleParisDelivery=true;if(target==='private')s.completed.privateDelivery=true}
    if(action==='claim_offer'&&s.claim.state==='submitted'){s.claim.state='offered';s.claim.resolution='replacement'}
    if(action==='claim_execute'&&s.claim.state==='execution_pending'){s.claim.executed=Math.min(s.claim.quantity,s.claim.executed+1);if(s.claim.executed===s.claim.quantity)s.claim.state='resolved'}
    if(action==='claim_close'&&s.claim.state==='resolved'){s.claim.state='closed';s.completed.claimClosed=true}
    if(action==='reorder_brand_approve'&&s.reorder.status==='buyer_approved')s.reorder.status='brand_approved';
    if(action==='reorder_convert'&&s.reorder.status==='brand_approved'){const r=s.reorder;r.status='converted';r.newOrder={code:'WH-R'+String(Date.now()).slice(-4),client:s.wholesaleOrders[r.store].client,stage:'draft',total:'€ 6,480',rev:1,shipment:'Not allocated',store:r.store};s.completed.reorderConverted=true}
    const claimActionName=action.startsWith('claim_');s.events=[{at:new Date().toISOString(),type:'admin_'+action,detail:(claimActionName?s.claim.id:action.startsWith('reorder_')?s.reorder.style:o?.code)+' → '+(claimActionName?s.claim.state:action.startsWith('reorder_')?s.reorder.status:o?.stage)},...(s.events||[])].slice(0,80);return s
  });renderAdmin();renderPrivate();renderWholesale();renderQA();toast('Admin action executed')
}
function claimAction(action){
  mutateDemo(s=>{const c=s.claim;
    if(action==='submit'&&s.privateOrder.stage==='delivered'){c.state='submitted';c.executed=0;c.resolution=null}
    if(action==='accept'&&c.state==='offered')c.state='execution_pending';
    if(action==='review'&&c.state==='offered')c.state='submitted';
    s.events=[{at:new Date().toISOString(),type:'claim_'+action,detail:c.id+' → '+c.state},...(s.events||[])].slice(0,80);return s
  });renderPrivate();renderAdmin();renderQA();toast('Claim: '+prettyStage(demoStore().claim.state))
}
function reorderAction(action){
  mutateDemo(s=>{const r=s.reorder;if(action==='system_propose'&&r.status==='none')r.status='proposed';if(action==='buyer_approve'&&r.status==='proposed')r.status='buyer_approved';s.events=[{at:new Date().toISOString(),type:'reorder_'+action,detail:r.style+' → '+r.status},...(s.events||[])].slice(0,80);return s});renderWholesale();renderAdmin();renderQA();toast('Reorder: '+demoStore().reorder.status)
}
function resetDemo(){demoReplace(seedDemo());renderCatalog();renderPrivate();renderWholesale();renderAdmin();renderReadiness();renderQA();toast('Demo state reset to v31.5 seed')}

const I={ru:{home:'Главная',catalog:'Коллекции',private:'Private',wholesale:'Wholesale',admin:'Admin',readiness:'Готовность',qa:'QA',login:'Вход',logout:'Выход'},en:{home:'Home',catalog:'Collections',private:'Private',wholesale:'Wholesale',admin:'Admin',readiness:'Readiness',qa:'QA',login:'Login',logout:'Logout'},it:{home:'Home',catalog:'Collezioni',private:'Private',wholesale:'Wholesale',admin:'Admin',readiness:'Readiness',qa:'QA',login:'Accedi',logout:'Esci'}};
