  privateTabs.innerHTML=Object.entries(pTabs).map(([k,v])=>`<button class="tab ${S.privateTab===k?'active':''}" data-ptab="${k}">${v}</button>`).join('');
  const wishlistProducts=products.filter(p=>(ds.wishlist||[]).includes(String(p.id)));
  const orderActions=[];
